 "content": "def transform(grid):
    """Mark the midpoint between horizontally adjacent foreground markers."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c - 1] == row[c + 1] and row[c] != row[c - 1]:
                # The marker color is the non-background color in this ARC task.
                if row[c - 1] == 0:
                    out[r][c] = 2
                elif row[c - 1] == 4:
                    out[r][c] = 2
    return out

